
CREATE Procedure [dbo].[ManagerReport]
@ManagerDate DateTime,
@AvailableRoom int,
@CompanyRecID int
as

Select 
DefaultDate as ManagerDate,
IsNull(Sum(y.RoomCapacity),0) as DailyRoomCap,
IsNull(Sum(y.BedCapacity),0)  as DailyBedCap,
IsNull(Sum(y.RoomCapacity),0)*(Cast(@ManagerDate-cast( Cast(Month(@ManagerDate) as VarChar(2))+'/'+'01'+'/'+Cast(Year(@ManagerDate) as VarChar(4)) as DateTime) as Int)+1) as MonthlyRoomCap,
IsNull(Sum(y.BedCapacity),0)*(Cast(@ManagerDate-cast( Cast(Month(@ManagerDate) as VarChar(2))+'/'+'01'+'/'+Cast(Year(@ManagerDate) as VarChar(4)) as DateTime) as Int)+1) as MonthlyBedCap,
IsNull(Sum(y.RoomCapacity),0)*(Cast(@ManagerDate-cast('01'+'/'+'01'+'/'+Cast(Year(@ManagerDate) as VarChar(4)) as DateTime) as Int)+1) as YearlyRoomCap,
IsNull(Sum(y.BedCapacity),0)*(Cast(@ManagerDate-cast('01'+'/'+'01'+'/'+Cast(Year(@ManagerDate) as VarChar(4)) as DateTime) as Int)+1) as YearlyBedCap,
(Select IsNull(Sum(Reservation.RoomNummer),0) From Reservation Where Reservation.CompanyRecId=@CompanyRecID and Status >0 And Recorddate >= @ManagerDate And RecordDate < (@ManagerDate+1)) as Records,
(Select IsNull(Sum(Reservation.RoomNummer),0) From Reservation Where Reservation.CompanyRecId=@CompanyRecID and Status =-1 And Canceldate = @ManagerDate ) as Cancel,
(Select IsNull(Sum(Reservation.RoomNummer),0) From Reservation Where Reservation.CompanyRecId=@CompanyRecID and Status >0 And Salesdate = @ManagerDate) as BookingReservation,
(Select Count(*) From resUpdate, Room Where Room.CompanyRecId=@CompanyRecID and resUpdate.CompanyRecId=@CompanyRecID and Room.Room = resUpdate.NewValue And ActionType=3 And Hoteldate = @ManagerDate) as RoomChange,
(Select Count(*) From resUpdate Where  resUpdate.CompanyRecId=@CompanyRecID and ActionType=2 And Hoteldate = @ManagerDate) as Early,
(Select Count(*) From resUpdate Where resUpdate.CompanyRecId=@CompanyRecID and ActionType=1 And Hoteldate = @ManagerDate) as Extention,
(Select IsNull(Sum(RoomNummer),0) From DailyDetail With (NoLock) Where DailyDetail.CompanyRecId=@CompanyRecID and Staydate = @ManagerDate And ReservationId = 0 And Status = 3) as DailyOOORoom,
(Select IsNull(Sum(RoomNummer),0) From DailyDetail With (NoLock) Where DailyDetail.CompanyRecId=@CompanyRecID and Staydate = @ManagerDate And ReservationId = 0 And Status = 2) as DailyOOSRoom,
(Select IsNull(Sum(DailyDetail.RoomNummer*RoomType.Capacity),0) From DailyDetail With (NoLock), Room, RoomType Where DailyDetail.CompanyRecId=@CompanyRecID and Room.CompanyRecId=@CompanyRecID and RoomType.CompanyRecId=@CompanyRecID and
 Staydate = @ManagerDate And ReservationId = 0 And Status = 3 
And Room.RoomTypeCode = RoomType.RoomTypeCode And Room.Room = DailyDetail.Room
) as DailyOOOBed,
(Select IsNull(Sum(DailyDetail.RoomNummer*RoomType.Capacity),0) From DailyDetail With (NoLock), Room, RoomType Where DailyDetail.CompanyRecId=@CompanyRecID and Room.CompanyRecId=@CompanyRecID and RoomType.CompanyRecId=@CompanyRecID and Staydate = @ManagerDate And ReservationId = 0 And Status = 2 
And Room.RoomTypeCode = RoomType.RoomTypeCode And Room.Room = DailyDetail.Room
) as DailyOOSBed,

(Select IsNull(Sum(Reservation.RoomNummer),0) From Reservation Where Reservation.CompanyRecId=@CompanyRecID and Status >0 And Recorddate >= DateAdd(year, -1, @ManagerDate) And RecordDate < DateAdd(year, -1, @ManagerDate)) as LY_Records,
(Select IsNull(Sum(Reservation.RoomNummer),0) From Reservation Where Reservation.CompanyRecId=@CompanyRecID and Status =-1 And Canceldate = DateAdd(year, -1, @ManagerDate) ) as LY_Cancel,
(Select IsNull(Sum(Reservation.RoomNummer),0) From Reservation Where Reservation.CompanyRecId=@CompanyRecID and Status >0 And Salesdate = DateAdd(year, -1, @ManagerDate)) as LY_BookingReservation,


(Select Count(*) From resUpdate, Room Where resUpdate.CompanyRecId=@CompanyRecID and Room.CompanyRecId=@CompanyRecID and Room.Room = resUpdate.NewValue And ActionType=3 And Hoteldate = DateAdd(year, -1, @ManagerDate)  ) as LY_RoomChange,
(Select Count(*) From resUpdate Where resUpdate.CompanyRecId=@CompanyRecID and ActionType=2 And Hoteldate = DateAdd(year, -1, @ManagerDate)) as LY_Early,
(Select Count(*) From resUpdate Where resUpdate.CompanyRecId=@CompanyRecID and ActionType=1 And Hoteldate = DateAdd(year, -1, @ManagerDate)) as LY_Extention,
(Select IsNull(Sum(RoomNummer),0) From DailyDetail With (NoLock) Where DailyDetail.CompanyRecId=@CompanyRecID and Staydate = DateAdd(year, -1, @ManagerDate) And ReservationId = 0 And Status = 3) as LY_DailyOOORoom,
(Select IsNull(Sum(RoomNummer),0) From DailyDetail With (NoLock) Where DailyDetail.CompanyRecId=@CompanyRecID and Staydate = DateAdd(year, -1, @ManagerDate) And ReservationId = 0 And Status = 2) as LY_DailyOOSRoom,
(Select IsNull(Sum(DailyDetail.RoomNummer*RoomType.Capacity),0) From DailyDetail With (NoLock), Room, RoomType Where DailyDetail.CompanyRecId=@CompanyRecID and Room.CompanyRecId=@CompanyRecID and RoomType.CompanyRecId=@CompanyRecID and Staydate = DateAdd(year, -1, @ManagerDate) And ReservationId = 0 And Status = 3 
And Room.RoomTypeCode = RoomType.RoomTypeCode And Room.Room = DailyDetail.Room
) as LY_DailyOOOBed,
(Select IsNull(Sum(DailyDetail.RoomNummer*RoomType.Capacity),0) From DailyDetail With (NoLock), Room, RoomType Where DailyDetail.CompanyRecId=@CompanyRecID and Room.CompanyRecId=@CompanyRecID and RoomType.CompanyRecId=@CompanyRecID and  Staydate = DateAdd(year, -1, @ManagerDate) And ReservationId = 0 And Status = 2 
And Room.RoomTypeCode = RoomType.RoomTypeCode And Room.Room = DailyDetail.Room
) as LY_DailyOOSBed,




(SELECT     IsNull(Sum(LocalAmount),0)
FROM         Department D ,
                      Folio F Where D.CompanyRecId=@CompanyRecID and F.CompanyRecId=@CompanyRecID and D.DepartCode = F.DepartCode 
And F.Deleted = 0 And F.PostDate < @ManagerDate And F.PostDate >= cast('01'+'/'+'01'+'/'+Cast(Year(@ManagerDate) as VarChar(4)) as DateTime) and F.OperationType <>7) As PreviosBalance,

(Select Sum(Invoice) FRom ExchangeRate Where ExchangeRate.CompanyRecId=@CompanyRecID and CurrencyCode = 'EUR' and Currdate = @ManagerDate) as EURDaily,
(Select Sum(Invoice)/Count(Invoice) FRom ExchangeRate Where ExchangeRate.CompanyRecId=@CompanyRecID and CurrencyCode = 'EUR' and Currdate <= @ManagerDate And CurrDate >= cast( Cast(Month(@ManagerDate) as VarChar(2))+'/'+'01'+'/'+Cast(Year(@ManagerDate) as VarChar(4)) as DateTime)) as EURMonth,
(Select Sum(Invoice)/Count(Invoice) FRom ExchangeRate Where ExchangeRate.CompanyRecId=@CompanyRecID and CurrencyCode = 'EUR' and Currdate <= @ManagerDate And CurrDate >= cast('01'+'/'+'01'+'/'+Cast(Year(@ManagerDate) as VarChar(4)) as DateTime)) as EURYear,

(Select Sum(Invoice) FRom ExchangeRate Where ExchangeRate.CompanyRecId=@CompanyRecID and CurrencyCode = 'USD' and Currdate = @ManagerDate) as USDDaily,
(Select Sum(Invoice)/Count(Invoice) FRom ExchangeRate Where ExchangeRate.CompanyRecId=@CompanyRecID and CurrencyCode = 'USD' and Currdate <= @ManagerDate And CurrDate >= cast( Cast(Month(@ManagerDate) as VarChar(2))+'/'+'01'+'/'+Cast(Year(@ManagerDate) as VarChar(4)) as DateTime)) as USDMonth,
(Select Sum(Invoice)/Count(Invoice) FRom ExchangeRate Where ExchangeRate.CompanyRecId=@CompanyRecID and CurrencyCode = 'USD' and Currdate <= @ManagerDate And CurrDate >= cast('01'+'/'+'01'+'/'+Cast(Year(@ManagerDate) as VarChar(4)) as DateTime)) as USDYear,

(Select Sum(Invoice) FRom ExchangeRate Where ExchangeRate.CompanyRecId=@CompanyRecID and CurrencyCode = 'EUR' and Currdate = DateAdd(year, -1, @ManagerDate) ) as LY_EURDaily,
(Select Sum(Invoice) FRom ExchangeRate Where ExchangeRate.CompanyRecId=@CompanyRecID and CurrencyCode = 'USD' and Currdate = DateAdd(year, -1, @ManagerDate) ) as LY_USDDaily,

IsNull(Sum(y.DailyRoom),0)					as DailyRoom,
IsNull(Sum(y.DailyPax),0)					as DailyPax,
IsNull(Sum(y.DailyPChd),0)					as DailyPChd,
IsNull(Sum(y.DailyFChd),0)					as DailyFChd,
IsNull(Sum(y.DailyBby),0)					as DailyBby,
IsNull(Sum(y.DailySoldRoom),0)				as DailySoldRoom,
IsNull(Sum(y.DailysoldPax),0)				as DailysoldPax,
IsNull(Sum(y.DailysoldPChd),0)				as DailysoldPChd,
IsNull(Sum(y.DailysoldFChd),0)				as DailysoldFChd,
IsNull(Sum(y.DailysoldBby),0)				as DailysoldBaby,
IsNull(Sum(y.DailyCompRoom),0)				as DailyCompRoom,
IsNull(Sum(y.DailyCompPax),0)				as DailyCompPax,
IsNull(Sum(y.DailyCompPChd),0)				as DailyCompPChd,
IsNull(Sum(y.DailyCompFChd),0)				as DailyCompFChd,
IsNull(Sum(y.DailyCompBby),0)				as DailyCompBaby,
IsNull(Sum(y.DailyHouseRoom),0)				as DailyHouseRoom,
IsNull(Sum(y.DailyHousePax),0)				as DailyHousePax,
IsNull(Sum(y.DailyHousePChd),0)				as DailyHousePChd,
IsNull(Sum(y.DailyHouseFChd),0)				as DailyHouseFChd,
IsNull(Sum(y.DailyHouseBby),0)				as DailyHouseBaby,
IsNull(Sum(y.MonthlyRoom),0)				as MonthlyRoom,
IsNull(Sum(y.MonthlyPax),0)					as MonthlyPax,
IsNull(Sum(y.MonthlyPChd),0)				as MonthlyPChd,
IsNull(Sum(y.MonthlyFChd),0)				as MonthlyFChd,
IsNull(Sum(y.MonthlyBby),0)					as MonthlyBby,
IsNull(Sum(y.MonthlySoldRoom),0)			as MonthlySoldRoom,
IsNull(Sum(y.MonthlysoldPax),0)				as MonthlysoldPax,
IsNull(Sum(y.MonthlysoldPChd),0)			as MonthlysoldPChd,
IsNull(Sum(y.MonthlysoldFChd),0)			as MonthlysoldFChd,
IsNull(Sum(y.MonthlysoldBby),0)				as MonthlysoldBaby,
IsNull(Sum(y.MonthlyCompRoom),0)			as MonthlyCompRoom,
IsNull(Sum(y.MonthlyCompPax),0)				as MonthlyCompPax,
IsNull(Sum(y.MonthlyCompPChd),0)			as MonthlyCompPChd,
IsNull(Sum(y.MonthlyCompFChd),0)			as MonthlyCompFChd,
IsNull(Sum(y.MonthlyCompBby),0)				as MonthlyCompBaby,
IsNull(Sum(y.MonthlyHouseRoom),0)			as MonthlyHouseRoom,
IsNull(Sum(y.MonthlyHousePax),0)			as MonthlyHousePax,
IsNull(Sum(y.MonthlyHousePChd),0)			as MonthlyHousePChd,
IsNull(Sum(y.MonthlyHouseFChd),0)			as MonthlyHouseFChd,
IsNull(Sum(y.MonthlyHouseBby),0)			as MonthlyHouseBaby,
IsNull(Sum(y.YearlyRoom),0)					as YearlyRoom,
IsNull(Sum(y.YearlyPax),0)					as YearlyPax,
IsNull(Sum(y.YearlyPChd),0)					as YearlyPChd,
IsNull(Sum(y.YearlyFChd),0)					as YearlyFChd,
IsNull(Sum(y.YearlyBby),0)					as YearlyBby,
IsNull(Sum(y.YearlySoldRoom),0)				as YearlySoldRoom,
IsNull(Sum(y.YearlysoldPax),0)				as YearlysoldPax,
IsNull(Sum(y.YearlysoldPChd),0)				as YearlysoldPChd,
IsNull(Sum(y.YearlysoldFChd),0)				as YearlysoldFChd,
IsNull(Sum(y.YearlysoldBby),0)				as YearlysoldBaby,
IsNull(Sum(y.YearlyCompRoom),0)				as YearlyCompRoom,
IsNull(Sum(y.YearlyCompPax),0)				as YearlyCompPax,
IsNull(Sum(y.YearlyCompPChd),0)				as YearlyCompPChd,
IsNull(Sum(y.YearlyCompFChd),0)				as YearlyCompFChd,
IsNull(Sum(y.YearlyCompBby),0)				as YearlyCompBby,
IsNull(Sum(y.YearlyHouseRoom),0)			as YearlyHouseRoom,
IsNull(Sum(y.YearlyHousePax),0)				as YearlyHousePax,
IsNull(Sum(y.YearlyHousePChd),0)			as YearlyHousePChd,
IsNull(Sum(y.YearlyHouseFChd),0)			as YearlyHouseFChd,
IsNull(Sum(y.YearlyHouseBby),0)				as YearlyHouseBaby,
IsNull(Sum(y.DailyRoomRevenueLocal),0)		as DailyRoomRevenue,
IsNull(Sum(y.DailyRoomRevenueEUR),0)		as DailyRoomRevenueForeign,
IsNull(Sum(y.DailyRoomRevenueUSD),0)		as DailyRoomRevenueForeignUSD,
IsNull(Sum(y.MonthlyRoomRevenueLocal),0)	as MonthlyRoomRevenue,
IsNull(Sum(y.MonthlyRoomRevenueEUR),0)		as MonthlyRoomRevenueForeign,
IsNull(Sum(y.MonthlyRoomRevenueUSD),0)		as MonthlyRoomRevenueForeignUSD,
Isnull(Sum(y.YearlyRoomRevenueLocal),0)		as YearlyRoomRevenue,
Isnull(Sum(y.YearlyRoomRevenueEUR),0)		as YearlyRoomRevenueForeign,
Isnull(Sum(y.YearlyRoomRevenueUSD),0)		as YearlyRoomRevenueForeignUSD,
IsNull(Sum(y.DailyExtraRevenueLocal),0)		as DailyExtraRevenue,
IsNull(Sum(y.DailyExtraRevenueEUR),0)		as DailyExtraRevenueForeign,
IsNull(Sum(y.DailyExtraRevenueUSD),0)		as DailyExtraRevenueForeignUSD,
IsNull(Sum(y.MonthlyExtraRevenueLocal),0)	as MonthlyExtraRevenue,
IsNull(Sum(y.MonthlyExtraRevenueEUR),0)		as MonthlyExtraRevenueForeign,
IsNull(Sum(y.MonthlyExtraRevenueUSD),0)		as MonthlyExtraRevenueForeignUSD,
Isnull(Sum(y.YearlyExtraRevenueLocal),0)	as YearlyExtraRevenue,
Isnull(Sum(y.YearlyExtraRevenueEUR),0)		as YearlyExtraRevenueForeign,
Isnull(Sum(y.YearlyExtraRevenueUSD),0)		as YearlyExtraRevenueForeignUSD,
Isnull(Sum(y.DailyCashRevenueLocal),0)		as DailyCashPaymentRevenue,
Isnull(Sum(y.DailyCashRevenueEUR),0)		as DailyCashPaymentRevenueForeign,
Isnull(Sum(y.DailyCashRevenueUSD),0)		as DailyCashPaymentRevenueForeignUSD,
Isnull(Sum(y.MonthlyCashRevenueLocal),0)	as MonthlyCashPaymentRevenue,
Isnull(Sum(y.MonthlyCashRevenueEUR),0)		as MonthlyCashPaymentRevenueForeign,
Isnull(Sum(y.MonthlyCashRevenueUSD),0)		as MonthlyCashPaymentRevenueForeignUSD,
Isnull(Sum(y.YearlyCashRevenueLocal),0)		as YearlyCashPaymentRevenue,
Isnull(Sum(y.YearlyCashRevenueEUR),0)		as YearlyCashPaymentRevenueForeign,
Isnull(Sum(y.YearlyCashRevenueUSD),0)		as YearlyCashPaymentRevenueForeignUSD,
IsNull(Sum(y.DailyCreditCardRevenueLocal),0)as DailyCCPaymentRevenue,
IsNull(Sum(y.DailyCreditCardRevenueEUR),0)	as DailyCCPaymentRevenueForeign,
IsNull(Sum(y.DailyCreditCardRevenueUSD),0)	as DailyCCPaymentRevenueForeignUSD,
IsNull(Sum(y.MonthlyCreditCardRevenueLocal),0)	as MonthlyCCPaymentRevenue,
IsNull(Sum(y.MonthlyCreditCardRevenueEUR),0)	as MonthlyCCPaymentRevenueForeign,
IsNull(Sum(y.MonthlyCreditCardRevenueUSD),0)	as MonthlyCCPaymentRevenueForeignUSD,
IsNull(Sum(y.YearlyCreditCardRevenueLocal),0)	as YearlyCCPaymentRevenue,
IsNull(Sum(y.YearlyCreditCardRevenueEUR),0)	as YearlyCCPaymentRevenueForeign,
IsNull(Sum(y.YearlyCreditCardRevenueUSD),0)	as YearlyCCPaymentRevenueForeignUSD,
IsNull(Sum(y.DailyCLRevenueLocal),0)			as DailyCLRevenue,
IsNull(Sum(y.DailyCLRevenueEUR),0)			as DailyCLRevenueForeign,
IsNull(Sum(y.DailyCLRevenueUSD),0)			as DailyCLRevenueForeignUSD,
IsNull(Sum(y.MonthlyCLRevenueLocal),0)		as MonthlyCLRevenue,
IsNull(Sum(y.MonthlyCLRevenueEUR),0)			as MonthlyCLRevenueForeign,
IsNull(Sum(y.MonthlyCLRevenueUSD),0)			as MonthlyCLRevenueForeignUSD,
IsNull(Sum(y.YearlyCLRevenueLocal),0)			as YearlyCLRevenue,
IsNull(Sum(y.YearlyCLRevenueEUR),0)			as YearlyCLRevenueForeign,
IsNull(Sum(y.YearlyCLRevenueUSD),0)			as YearlyCLRevenueForeignUSD,
IsNull(Sum(y.DailyCompRoomRevenueLocal),0)	as DailyRoomRevenueComp,
IsNull(Sum(y.DailyCompRoomRevenueEUR),0)		as DailyEURRoomRevenueComp,
IsNull(Sum(y.DailyCompRoomRevenueUSD),0)		as DailyUSDRoomRevenueComp,
IsNull(Sum(y.MonthlyCompRoomRevenueLocal),0)	as MonthlyRoomRevenueComp,
IsNull(Sum(y.MonthlyCompRoomRevenueEUR),0)	as MonthlyEURRoomRevenueComp,
IsNull(Sum(y.MonthlyCompRoomRevenueUSD),0)	as MonthlyUSDRoomRevenueComp,
IsNull(Sum(y.YearlyCompRoomRevenueLocal),0)	as YearlyRoomRevenueComp,
IsNull(Sum(y.YearlyCompRoomRevenueEUR),0)		as YearlyEURRoomRevenueComp,
IsNull(Sum(y.YearlyCompRoomRevenueUSD),0)		as YearlyUSDRoomRevenueComp,
IsNull(Sum(y.DailyCompExtraRevenueLocal),0)	as DailyExtraRevenueComp,
IsNull(Sum(y.DailyCompExtraRevenueEUR),0)		as DailyEURExtraRevenueComp,
IsNull(Sum(y.DailyCompExtraRevenueUSD),0)		as DailyUSDExtraRevenueComp,
IsNull(Sum(y.MonthlyCompExtraRevenueLocal),0)	as MonthlyExtraRevenueComp,
IsNull(Sum(y.MonthlyCompExtraRevenueEUR),0)	as MonthlyEURExtraRevenueComp,
IsNull(Sum(y.MonthlyCompExtraRevenueUSD),0)	as MonthlyUSDExtraRevenueComp,
IsNull(Sum(y.YearlyCompExtraRevenueLocal),0)	as YearlyExrtaRevenueComp,
IsNull(Sum(y.YearlyCompExtraRevenueEUR),0)	as YearlyEURExtraRevenueComp,
IsNull(Sum(y.YearlyCompExtraRevenueUSD),0)	as YearlyUSDExrtaRevenueComp,
IsNull(Sum(y.DailyVORoomRevenueLocal),0)		as DailyVORoomRevenue,
IsNull(Sum(y.DailyVORoomRevenueEUR),0)		as DailyVORoomRevenueForeign,
IsNull(Sum(y.DailyVORoomRevenueUSD),0)		as DailyVORoomRevenueForeignUSD,
IsNull(Sum(y.MonthlyVORoomRevenueLocal),0)	as MonthlyVORoomRevenue,
IsNull(Sum(y.MonthlyVORoomRevenueEUR),0)		as MonthlyVORoomRevenueForeign,
IsNull(Sum(y.MonthlyVORoomRevenueUSD),0)		as MonthlyVORoomRevenueForeignUSD,
IsNull(Sum(y.YearlyVORoomRevenueLocal),0)		as YearlyVORoomRevenue,
IsNull(Sum(y.YearlyVORoomRevenueEUR),0)		as YearlyVORoomRevenueForeign,
IsNull(Sum(y.YearlyVORoomRevenueUSD),0)		as YearlyVORoomRevenueForeignUSD,
IsNull(Sum(y.DailySngRoom),0)				as DailySngRoom,
IsNull(Sum(y.DailyDblRoom),0)				as DailyDblRoom,
IsNull(Sum(y.DailyTrpRoom),0)				as DailyTrpRoom,
IsNull(Sum(y.DailyQuaRoom),0)				as DailyQuaRoom,
IsNull(Sum(y.MonthlySngRoom),0)				as MonthlySngRoom,
IsNull(Sum(y.MonthlyDblRoom),0)				as MonthlyDblRoom,
IsNull(Sum(y.MonthlyTrpRoom),0)				as MonthlyTrpRoom,
IsNull(Sum(y.MonthlyQuaRoom),0)				as MonthlyQuaRoom,
IsNull(Sum(y.YearlySngRoom),0)				as YearlySngRoom,
IsNull(Sum(y.YearlyDblRoom),0)				as YearlyDblRoom,
IsNull(Sum(y.YearlyTrpRoom),0)				as YearlyTrpRoom,
IsNull(Sum(y.YearlyQuaRoom),0)				as YearlyQuaRoom,
IsNull(Sum(y.DailySngPax),0)				as DailySngPax,
IsNull(Sum(y.DailyDblPax),0)				as DailyDblPax,
IsNull(Sum(y.DailyTrpPax),0)				as DailyTrpPax,
IsNull(Sum(y.DailyQuaPax),0)				as DailyQuaPax,
IsNull(Sum(y.MonthlySngPax),0)				as MonthlySngPax,
IsNull(Sum(y.MonthlyDblPax),0)				as MonthlyDblPax,
IsNull(Sum(y.MonthlyTrpPax),0)				as MonthlyTrpPax,
IsNull(Sum(y.MonthlyQuaPax),0)				as MonthlyQuaPax,
IsNull(Sum(y.YearlySngPax),0)				as YearlySngPax,
IsNull(Sum(y.YearlyDblPax),0)				as YearlyDblPax,
IsNull(Sum(y.YearlyTrpPax),0)				as YearlyTrpPax,
IsNull(Sum(y.YearlyQuaPax),0)				as YearlyQuaPax,
IsNull(Sum(y.DailySngRoomRevenue),0)		as DailySngRoomRevenue,
IsNull(Sum(y.DailyDblRoomRevenue),0)		as DailyDblRoomRevenue,
IsNull(Sum(y.DailyTrpRoomRevenue),0)		as DailyTrpRoomRevenue,
IsNull(Sum(y.DailyQuaRoomRevenue),0)		as DailyQuaRoomRevenue,
IsNull(Sum(y.MonthlySngRoomRevenue),0)		as MonthSngRoomRevenue,
IsNull(Sum(y.MonthlyDblRoomRevenue),0)		as MonthDblRoomRevenue,
IsNull(Sum(y.MonthlyTrpRoomRevenue),0)		as MonthTrpRoomRevenue,
IsNull(Sum(y.MonthlyQuaRoomRevenue),0)		as MonthQuaRoomRevenue,
IsNull(Sum(y.YearlySngRoomRevenue),0)		as YearSngRoomRevenue,
IsNull(Sum(y.YearlyDblRoomRevenue),0)		as YearDblRoomRevenue,
IsNull(Sum(y.YearlyTrpRoomRevenue),0)		as YearTrpRoomRevenue,
IsNull(Sum(y.YearlyQuaRoomRevenue),0)		as YearQuaRoomRevenue,
Isnull(Sum(y.MonthlyOOORoom),0)				as MonthOOORoom,
Isnull(Sum(y.MonthlyOOSRoom),0)				as MonthOOSRoom,
Isnull(Sum(y.MonthlyOOOBed),0)				as MonthlyOOOBed,
Isnull(Sum(y.MonthlyOOSBed),0)				as MonthlyOOSBed,
Isnull(Sum(y.YearlyOOORoom),0)				as YearOOORoom,
Isnull(Sum(y.YearlyOOSRoom),0)				as YearOOSRoom,
Isnull(Sum(y.YearlyOOOBed),0)				as YearlyOOOBed,
Isnull(Sum(y.YearlyOOSBed),0)				as YearlyOOSBed,
IsNull(Sum(y.DailyVOExtraRevenueLocal),0)	as DailyVOExtraRevenue,
IsNull(Sum(y.DailyVOExtraRevenueEUR),0)		as DailyVOExtraRevenueForeign,
IsNull(Sum(y.DailyVOExtraRevenueUSD),0)		as DailyVOExtraRevenueForeignUSD,
IsNull(Sum(y.MonthlyVOExtraRevenueLocal),0)	as MonthlyVOExtraRevenue,
IsNull(Sum(y.MonthlyVOExtraRevenueEUR),0)	as MonthlyVOExtraRevenueForeign,
IsNull(Sum(y.MonthlyVOExtraRevenueUSD),0)	as MonthlyVOExtraRevenueForeignUSD,  
IsNull(Sum(y.YearlyVOExtraRevenueLocal),0)	as YearlyVOExtraRevenue,
IsNull(Sum(y.YearlyVOExtraRevenueEUR),0)	as YearlyVOExtraRevenueForeign,
IsNull(Sum(y.YearlyVOExtraRevenueUSD),0)	as YearlyVOExtraRevenueForeignUSD,
IsNull(Sum(y.DailyChd1),0)					as DailyChd1,
IsNull(Sum(y.DailyChd7),0)					as DailyChd7,
IsNull(Sum(y.MonthChd1),0)					as MonthChd1,
IsNull(Sum(y.MonthChd7),0)					as MonthChd7,
IsNull(Sum(y.YearChd1),0)					as YearChd1,
IsNull(Sum(y.YearChd7),0)					as YearChd7,
IsNull(Sum(y.DailyRoomRevenueLocal),0)	/   Case When IsNull(Sum(y.DailySoldRoom),1) = 0 Then 1 Else IsNull(Sum(y.DailySoldRoom),1) End 	as DailySoldRoomAvr,
IsNull(Sum(y.DailyRoomRevenueLocal),0)	/   Case When (IsNull(Sum(y.DailySoldPax),1)+(IsNull(Sum(y.DailyPChd),1)/2)) = 0 Then 1 Else (IsNull(Sum(y.DailySoldPax),1)+(IsNull(Sum(y.DailyPChd),1)/2))		end as DailySoldPaxAvr,
IsNull(Sum(y.DailyRoomRevenueLocal),0)	/ Case When IsNull(Sum(y.DailyRoom),1)= 0 Then 1 Else IsNull(Sum(y.DailyRoom),1)	end as DailyRoomAvr,
IsNull(Sum(y.DailyRoomRevenueLocal),0)	/ Case When (IsNull(Sum(y.DailyPax),1)+(IsNull(Sum(y.DailyPChd),1)/2))= 0 Then 1 Else (IsNull(Sum(y.DailyPax),1)+(IsNull(Sum(y.DailyPChd),1)/2))		end as DailyPaxAvr,
IsNull(Sum(y.DailyRoomRevenueEUR),0)	/ Case When IsNull(Sum(y.DailySoldRoom),1)= 0 Then 1 Else IsNull(Sum(y.DailySoldRoom),1)	end as DailySoldRoomAvrEUR,
