(Cast(IsNull(Sum(y.LY_DailySngRoom),1) as Numeric(19,5))*100)/ Case When IsNull(Sum(y.LY_DailySoldRoom),1) = 0 Then 1 Else IsNull(Sum(y.LY_DailySoldRoom),1) end as LY_DailySngSoldRoomRatio,
