(Cast(IsNull(Sum(y.LY_DailySoldRoom),1) as Numeric(19,5))*100) / (Select Count(*) From Room Where Room.CompanyRecId=@CompanyRecID and Room.Forecast = 1)  as LY_DailySoldRoomRatio,
(Cast(IsNull(Sum(y.LY_DailyRoom),1) as Numeric(19,5))*100) / (Select Count(*) From Room Where Room.CompanyRecId=@CompanyRecID and Room.Forecast = 1)  as LY_DailyRoomRatio,
--
(Cast(IsNull(Sum(y.LY_DailyCompRoom),1) as Numeric(19,5))*100) / (Select Count(*) From Room Where Room.CompanyRecId=@CompanyRecID and Room.Forecast = 1)  as LY_DailyCompRoomRatio,
