IsNull(Sum(y.LY_DailyRoomRevenueLocal),0)*0.50 as LY_DailyRoomRevenueLocalCost,
IsNull(Sum(y.LY_DailyRoomRevenueEUR),0)*0.50 as LY_DailyRoomRevenueEURCost,
