(IsNull(Sum(y.LY_DailyRoomRevenueUSD),0)-IsNull(Sum(y.LY_DailyCompRoomRevenueUSD),0)) / Case When IsNull(Sum(y.LY_DailySoldRoom),0)=0 Then 1 Else IsNull(Sum(y.LY_DailySoldRoom),0) end as LY_DailyNetRoomAvrUSD,

(IsNull(Sum(y.LY_DailyRoomRevenueLocal),0)-IsNull(Sum(y.LY_DailyCompRoomRevenueLocal),0)) / Case When (IsNull(Sum(y.LY_DailySoldPax),1)+(IsNull(Sum(y.LY_DailyPChd),1)/2))=0 Then 1 Else (IsNull(Sum(y.LY_DailySoldPax),1)+(IsNull(Sum(y.LY_DailyPChd),1)/2)) end  as LY_DailyNetPaxAvrLocal,
(IsNull(Sum(y.LY_DailyRoomRevenueEUR),0)-IsNull(Sum(y.LY_DailyCompRoomRevenueEUR),0)) / Case When (IsNull(Sum(y.LY_DailySoldPax),1)+(IsNull(Sum(y.LY_DailyPChd),1)/2))=0 Then 1 Else (IsNull(Sum(y.LY_DailySoldPax),1)+(IsNull(Sum(y.LY_DailyPChd),1)/2)) end as LY_DailyNetPaxAvrEUR,
(IsNull(Sum(y.LY_DailyRoomRevenueUSD),0)-IsNull(Sum(y.LY_DailyCompRoomRevenueUSD),0)) / Case When (IsNull(Sum(y.LY_DailySoldPax),1)+(IsNull(Sum(y.LY_DailyPChd),1)/2))=0 Then 1 Else (IsNull(Sum(y.LY_DailySoldPax),1)+(IsNull(Sum(y.LY_DailyPChd),1)/2)) end as LY_DailyNetPaxAvrUSD,


