(IsNull(Sum(y.LY_DailyExtraRevenueEUR),0)-IsNull(Sum(y.LY_DailyCompExtraRevenueEUR),0)) / Case When (IsNull(Sum(y.LY_DailySoldPax),1)+(IsNull(Sum(y.LY_DailyPChd),1)/2))=0 Then 1 Else (IsNull(Sum(y.LY_DailySoldPax),1)+(IsNull(Sum(y.LY_DailyPChd),1)/2)) end as LY_DailyNetExtraPaxAvrEUR,
(IsNull(Sum(y.LY_DailyExtraRevenueUSD),0)-IsNull(Sum(y.LY_DailyCompExtraRevenueUSD),0)) / Case When (IsNull(Sum(y.LY_DailySoldPax),1)+(IsNull(Sum(y.LY_DailyPChd),1)/2))=0 Then 1 Else (IsNull(Sum(y.LY_DailySoldPax),1)+(IsNull(Sum(y.LY_DailyPChd),1)/2)) end as LY_DailyNetExtraPaxAvrUSD,

IsNull(Sum(y.LY_DailyRoomRevenueLocal),0)+IsNull(Sum(y.LY_DailyExtraRevenueLocal),0) as LY_DailyTotalRevenueLocal,
