From DefaultDate Left Outer Join
(
Select 
(Select Defaultdate From DefaultDate Where DefaultDate.CompanyRecId=@CompanyRecID and DefaultDate= @ManagerDate) as Date,
x.DailyRoom,
x.DailyPax,
x.DailyPChd,
x.DailyFChd,
X.DailyBby,
x.DailySoldRoom,
x.DailysoldPax,
x.DailysoldPChd,
x.DailysoldFChd,
X.DailysoldBby,
x.DailyCompRoom,
x.DailyCompPax,
x.DailyCompPChd,
x.DailyCompFChd,
X.DailyCompBby,
x.DailyHouseRoom,
x.DailyHousePax,
x.DailyHousePChd,
x.DailyHouseFChd,
X.DailyHouseBby,
0 as MonthlyRoom,
0 as MonthlyPax,
0 as MonthlyPChd,
0 as MonthlyFChd,
0 as MonthlyBby,
0 as MonthlySoldRoom,
0 as MonthlysoldPax,
0 as MonthlysoldPChd,
0 as MonthlysoldFChd,
0 as MonthlysoldBby,
0 as MonthlyCompRoom,
0 as MonthlyCompPax,
0 as MonthlyCompPChd,
0 as MonthlyCompFChd,
0 as MonthlyCompBby,
0 as MonthlyHouseRoom,
0 as MonthlyHousePax,
0 as MonthlyHousePChd,
0 as MonthlyHouseFChd,
0 as MonthlyHouseBby,
