From DefaultDate Left Outer Join
(
    Select D.StayDate,
	IsNull(Sum(D.RoomNummer),0) as DailyRoom,
	IsNull(Sum(D.RoomNummer*D.Pax),0) as DailyPax,
	IsNull(Sum(D.RoomNummer*D.PaidChild),0) as DailyPChd,
	IsNull(Sum(D.RoomNummer*D.FreeChild),0) as DailyFChd,
	IsNull(Sum(D.RoomNummer*D.Baby),0) as DailyBby,

	IsNull(Sum(Case When D.StayType < 4 Then D.RoomNummer Else 0 End),0) as DailySoldRoom,
	IsNull(Sum(Case When D.StayType < 4 Then D.RoomNummer*D.Pax Else 0 End),0) as DailySoldPax,
	IsNull(Sum(Case When D.StayType < 4 Then D.RoomNummer*D.PaidChild  Else 0 End),0) as DailySoldPChd,
	IsNull(Sum(Case When D.StayType < 4 Then D.RoomNummer*D.FreeChild Else 0 End),0) as DailySoldFChd,
	IsNull(Sum(Case When D.StayType < 4 Then D.RoomNummer*D.Baby Else 0 End),0) as DailySoldBby,

	IsNull(Sum(Case When D.StayType In (4,6) Then D.RoomNummer Else 0 End) ,0) as DailyCompRoom,
	IsNull(Sum(Case When D.StayType In (4,6) Then case D.RoomNummer when 0 then 1 else D.RoomNummer end *D.Pax Else 0 End),0) as DailyCompPax,
	IsNull(Sum(Case When D.StayType In (4,6) Then D.RoomNummer*D.PaidChild Else 0 End),0) as DailyCompPChd,
	IsNull(Sum(Case When D.StayType In (4,6) Then D.RoomNummer*D.FreeChild Else 0 End),0) as DailyCompFChd,
	IsNull(Sum(Case When D.StayType In (4,6) Then D.RoomNummer*D.Baby Else 0 End),0) as DailyCompBby,

	IsNull(Sum(Case When D.StayType =5 Then D.RoomNummer Else 0 End) ,0) as DailyHouseRoom,
	IsNull(Sum(Case When D.StayType =5 Then D.RoomNummer*D.Pax Else 0 End),0) as DailyHousePax,
	IsNull(Sum(Case When D.StayType =5 Then D.RoomNummer*D.PaidChild Else 0 End),0) as DailyHousePChd,
	IsNull(Sum(Case When D.StayType =5 Then D.RoomNummer*D.FreeChild Else 0 End),0) as DailyHouseFChd,
	IsNull(Sum(Case When D.StayType =5 Then D.RoomNummer*D.Baby Else 0 End),0) as DailyHouseBby,

	IsNull(Sum(Case When D.Pax =1 Then D.RoomNummer Else 0 End) ,0) as DailySngRoom,
	IsNull(Sum(Case When D.Pax =2 Then D.RoomNummer Else 0 End),0) as DailyDblRoom,
	IsNull(Sum(Case When D.Pax =3 Then D.RoomNummer Else 0 End),0) as DailyTrpRoom,
	IsNull(Sum(Case When D.Pax >=4 Then D.RoomNummer Else 0 End),0) as DailyQuaRoom,

	IsNull(Sum(Case When D.Pax =1 Then D.Pax Else 0 End) ,0) as DailySngPax,
	IsNull(Sum(Case When D.Pax =2 Then D.Pax Else 0 End),0) as DailyDblPax,
	IsNull(Sum(Case When D.Pax =3 Then D.Pax Else 0 End),0) as DailyTrpPax,
	IsNull(Sum(Case When D.Pax >=4 Then D.Pax Else 0 End),0) as DailyQuaPax,

	IsNull(Sum(Case When D.Child1<7 And D.Child1>0 Then 1 Else 0 end)+
		   Sum(Case When D.Child2<7 And D.Child2>0 Then 1 Else 0 end)+
		   Sum(Case When D.Child3<7 And D.Child3>0 Then 1 Else 0 end)+
		   Sum(Case When D.Child4<7 And D.Child4>0 Then 1 Else 0 end),0 ) 
		 As DailyChd1,

	IsNull(Sum(Case When D.Child1>=7  Then 1 Else 0 end)+
		   Sum(Case When D.Child2>=7  Then 1 Else 0 end)+
		   Sum(Case When D.Child3>=7  Then 1 Else 0 end)+
		   Sum(Case When D.Child4>=7  Then 1 Else 0 end),0 ) 
	As DailyChd7



	


	From DailyDetail D With (NoLock), Reservation R With (NoLock) Where R.CompanyRecId=@CompanyRecID and D.CompanyRecId=@CompanyRecID and R.RecId = D.ReservationId And R.Status>0 
	Group By D.StayDAte



)x On X.StayDate = Defaultdate.DefaultDate
Where DefaultDate.CompanyRecId=@CompanyRecID and DefaultDate = @ManagerDate
