0 as BedCapacity


From DefaultDate Left Outer Join
(
    Select D.StayDate,
	D.RoomNummer as MonthlyRoom,
	D.RoomNummer*D.Pax as MonthlyPax,
	D.RoomNummer*D.PaidChild as MonthlyPChd,
	D.RoomNummer*D.FreeChild as MonthlyFChd,
	D.RoomNummer*D.Baby as MonthlyBby,

	Case When D.StayType < 4 Then D.RoomNummer Else 0 End as MonthlySoldRoom,
	Case When D.StayType < 4 Then D.RoomNummer*D.Pax Else 0 End as MonthlySoldPax,
	Case When D.StayType < 4 Then D.RoomNummer*D.PaidChild  Else 0 End as MonthlySoldPChd,
	Case When D.StayType < 4 Then D.RoomNummer*D.FreeChild Else 0 End as MonthlySoldFChd,
	Case When D.StayType < 4 Then D.RoomNummer*D.Baby Else 0 End as MonthlySoldBby,

	Case When D.StayType In (4,6) Then D.RoomNummer Else 0 End as MonthlyCompRoom,
	Case When D.StayType In (4,6) Then (case D.RoomNummer when 0 then 1 else D.RoomNummer end )*D.Pax Else 0 End as MonthlyCompPax,
	Case When D.StayType In (4,6) Then D.RoomNummer*D.PaidChild Else 0 End as MonthlyCompPChd,
	Case When D.StayType In (4,6) Then D.RoomNummer*D.FreeChild Else 0 End as MonthlyCompFChd,
	Case When D.StayType In (4,6) Then D.RoomNummer*D.Baby Else 0 End as MonthlyCompBby,

	Case When D.StayType =5 Then D.RoomNummer Else 0 End  as MonthlyHouseRoom,
	Case When D.StayType =5 Then D.RoomNummer*D.Pax Else 0 End as MonthlyHousePax,
	Case When D.StayType =5 Then D.RoomNummer*D.PaidChild Else 0 End as MonthlyHousePChd,
	Case When D.StayType =5 Then D.RoomNummer*D.FreeChild Else 0 End as MonthlyHouseFChd,
	Case When D.StayType =5 Then D.RoomNummer*D.Baby Else 0 End as MonthlyHouseBby,

	Case When D.Pax =1 Then D.RoomNummer Else 0 End as MonthlySngRoom,
	Case When D.Pax =2 Then D.RoomNummer Else 0 End as MonthlyDblRoom,
	Case When D.Pax =3 Then D.RoomNummer Else 0 End as MonthlyTrpRoom,
	Case When D.Pax >=4 Then D.RoomNummer Else 0 End as MonthlyQuaRoom,

	Case When D.Pax =1 Then D.Pax Else 0 End as MonthlySngPax,
	Case When D.Pax =2 Then D.Pax Else 0 End as MonthlyDblPax,
	Case When D.Pax =3 Then D.Pax Else 0 End as MonthlyTrpPax,
	Case When D.Pax >=4 Then D.Pax Else 0 End as MonthlyQuaPax,

	Case When D.Child1<7 And D.Child1>0 Then 1 Else 0 end+
	Case When D.Child2<7 And D.Child2>0 Then 1 Else 0 end+
	Case When D.Child3<7 And D.Child3>0 Then 1 Else 0 end+
	Case When D.Child4<7 And D.Child4>0 Then 1 Else 0 end
		 As MonthChd1,

	Case When D.Child1>=7  Then 1 Else 0 end+
	Case When D.Child2>=7  Then 1 Else 0 end+
	Case When D.Child3>=7  Then 1 Else 0 end+
	Case When D.Child4>=7  Then 1 Else 0 end 
	As MonthChd7




	From DailyDetail D With (NoLock), Reservation R With (NoLock) Where R.CompanyRecId=@CompanyRecID and R.CompanyRecId=@CompanyRecID and R.RecId = D.ReservationId And R.Status>0 



