From DefaultDate Left Outer Join
(
    Select D.StayDate,
	D.RoomNummer as YearlyRoom,
	D.RoomNummer*D.Pax as YearlyPax,
	D.RoomNummer*D.PaidChild as YearlyPChd,
	D.RoomNummer*D.FreeChild as YearlyFChd,
	D.RoomNummer*D.Baby as YearlyBby,

	Case When D.StayType < 4 Then D.RoomNummer Else 0 End as YearlySoldRoom,
	Case When D.StayType < 4 Then D.RoomNummer*D.Pax Else 0 End as YearlySoldPax,
	Case When D.StayType < 4 Then D.RoomNummer*D.PaidChild  Else 0 End as YearlySoldPChd,
	Case When D.StayType < 4 Then D.RoomNummer*D.FreeChild Else 0 End as YearlySoldFChd,
	Case When D.StayType < 4 Then D.RoomNummer*D.Baby Else 0 End as YearlySoldBby,

	Case When D.StayType In (4,6) Then D.RoomNummer Else 0 End as YearlyCompRoom,
	Case When D.StayType In (4,6) Then (case D.RoomNummer when 0 then 1 else D.RoomNummer end )*D.Pax Else 0 End as YearlyCompPax,
	Case When D.StayType In (4,6) Then D.RoomNummer*D.PaidChild Else 0 End as YearlyCompPChd,
	Case When D.StayType In (4,6) Then D.RoomNummer*D.FreeChild Else 0 End as YearlyCompFChd,
	Case When D.StayType In (4,6) Then D.RoomNummer*D.Baby Else 0 End as YearlyCompBby,

	Case When D.StayType =5 Then D.RoomNummer Else 0 End  as YearlyHouseRoom,
	Case When D.StayType =5 Then D.RoomNummer*D.Pax Else 0 End as YearlyHousePax,
	Case When D.StayType =5 Then D.RoomNummer*D.PaidChild Else 0 End as YearlyHousePChd,
	Case When D.StayType =5 Then D.RoomNummer*D.FreeChild Else 0 End as YearlyHouseFChd,
	Case When D.StayType =5 Then D.RoomNummer*D.Baby Else 0 End as YearlyHouseBby,

	Case When D.Pax =1 Then D.RoomNummer Else 0 End as YearlySngRoom,
	Case When D.Pax =2 Then D.RoomNummer Else 0 End as YearlyDblRoom,
	Case When D.Pax =3 Then D.RoomNummer Else 0 End as YearlyTrpRoom,
	Case When D.Pax >=4 Then D.RoomNummer Else 0 End as YearlyQuaRoom,

	Case When D.Pax =1 Then D.Pax Else 0 End as YearlySngPax,
	Case When D.Pax =2 Then D.Pax Else 0 End as YearlyDblPax,
	Case When D.Pax =3 Then D.Pax Else 0 End as YearlyTrpPax,
	Case When D.Pax >=4 Then D.Pax Else 0 End as YearlyQuaPax,

	Case When D.Child1<7 And D.Child1>0 Then 1 Else 0 end+
	Case When D.Child2<7 And D.Child2>0 Then 1 Else 0 end+
	Case When D.Child3<7 And D.Child3>0 Then 1 Else 0 end+
	Case When D.Child4<7 And D.Child4>0 Then 1 Else 0 end 
	 As YearChd1,

	Case When D.Child1>=7  Then 1 Else 0 end+
	Case When D.Child2>=7  Then 1 Else 0 end+
	Case When D.Child3>=7  Then 1 Else 0 end+
	Case When D.Child4>=7  Then 1 Else 0 end 
	As YearChd7





	From DailyDetail D With (NoLock), Reservation R With (NoLock) Where D.CompanyRecId=@CompanyRecID and R.CompanyRecId=@CompanyRecID and R.RecId = D.ReservationId And R.Status>0 



