0 as LY_DailyTrpRoomRevenue,
0 as LY_DailyQuaRoomRevenue,
0 as RoomCapacity,
0 as BedCapacity


From DefaultDate Left Outer Join
(
	SELECT F.Postdate,
	LocalAmount as YearlyExtraRevenueLocal,
	LocalAmount/(1+(F.VatRatio*0.01)) as YearlyVOExtraRevenueLocal,
	Case When F.CurrencyCode = 'EUR' Then F.NetAmount Else F.NetAmount*(Dbo.FnFoundCurr(IsNull(F.CurrDate,F.Postdate),F.CurrencyCode,1,@CompanyRecId)/Dbo.FnFoundCurr(IsNull(F.CurrDate,F.PostDate),'EUR',1,@CompanyRecId))
	End As YearlyExtraRevenueEUR,

	Case When F.CurrencyCode = 'EUR' Then F.NetAmount/(1+(F.VatRatio*0.01)) Else (F.NetAmount/(1+(F.VatRatio*0.01)))*(Dbo.FnFoundCurr(IsNull(F.CurrDate,F.Postdate),F.CurrencyCode,1,@CompanyRecId)/Dbo.FnFoundCurr(IsNull(F.CurrDate,F.PostDate),'EUR',1,@CompanyRecId))
	End As YearlyVOExtraRevenueEUR,

	Case When F.CurrencyCode = 'USD' Then F.NetAmount Else F.NetAmount*(Dbo.FnFoundCurr(IsNull(F.CurrDate,F.Postdate),F.CurrencyCode,1,@CompanyRecId)/Dbo.FnFoundCurr(IsNull(F.CurrDate,F.PostDate),'USD',1,@CompanyRecId))
	End As YearlyExtraRevenueUSD	,

	Case When F.CurrencyCode = 'USD' Then F.NetAmount/(1+(F.VatRatio*0.01)) Else (F.NetAmount/(1+(F.VatRatio*0.01)))*(Dbo.FnFoundCurr(IsNull(F.CurrDate,F.Postdate),F.CurrencyCode,1,@CompanyRecId)/Dbo.FnFoundCurr(IsNull(F.CurrDate,F.PostDate),'USD',1,@CompanyRecId))
	End As YearlyVOExtraRevenueUSD	

	FROM         Department D With (NoLock), Folio F With (NoLock) Where F.CompanyRecId=@CompanyRecID and D.CompanyRecId=@CompanyRecID and  D.DepartCode = F.DepartCode AND D.DepartType = 2
				And F.Deleted = 0
)x On X.Postdate = Defaultdate.DefaultDate
Where  DefaultDate.CompanyRecId=@CompanyRecID and
DefaultDate<= @ManagerDate And DefaultDate >= cast('01'+'/'+'01'+'/'+Cast(Year(@ManagerDate) as VarChar(4)) as DateTime)	


