	IsNull(Sum(Case When D.CashType = 1 Then LocalAmount Else 0 End),0) as DailyCashRevenueLocal,
	IsNull(Sum(Case When D.CashType = 1 Then 
				Case When F.CurrencyCode = 'EUR' Then F.NetAmount Else F.NetAmount*(Dbo.FnFoundCurr(IsNull(F.CurrDate,F.Postdate),F.CurrencyCode,1,@CompanyRecId)/Dbo.FnFoundCurr(IsNull(F.CurrDate,F.PostDate),'EUR',1,@CompanyRecId))
				End
				Else 0 End),0) As DailyCashRevenueEUR,
	IsNull(Sum(Case When D.CashType = 1 Then
				Case When F.CurrencyCode = 'USD' Then F.NetAmount Else F.NetAmount*(Dbo.FnFoundCurr(IsNull(F.CurrDate,F.Postdate),F.CurrencyCode,1,@CompanyRecId)/Dbo.FnFoundCurr(IsNull(F.CurrDate,F.PostDate),'USD',1,@CompanyRecId))
				End
				Else 0 End),0) As DailyCashRevenueUSD,

	IsNull(Sum(Case When D.CashType = 2 Then LocalAmount Else 0 End),0) as DailyCreditCardRevenueLocal,
	IsNull(Sum(Case When D.CashType = 2 Then 
				Case When F.CurrencyCode = 'EUR' Then F.NetAmount Else F.NetAmount*(Dbo.FnFoundCurr(IsNull(F.CurrDate,F.Postdate),F.CurrencyCode,1,@CompanyRecId)/Dbo.FnFoundCurr(IsNull(F.CurrDate,F.PostDate),'EUR',1,@CompanyRecId))
				End
				Else 0 End),0) As DailyCreditCardRevenueEUR,
	IsNull(Sum(Case When D.CashType = 2 Then
				Case When F.CurrencyCode = 'USD' Then F.NetAmount Else F.NetAmount*(Dbo.FnFoundCurr(IsNull(F.CurrDate,F.Postdate),F.CurrencyCode,1,@CompanyRecId)/Dbo.FnFoundCurr(IsNull(F.CurrDate,F.PostDate),'USD',1,@CompanyRecId))
				End
				Else 0 End),0) As DailyCreditCardRevenueUSD	

	FROM         Department D With (NoLock), Folio F With (NoLock) Where F.CompanyRecId=@CompanyRecID and D.CompanyRecId=@CompanyRecID and  D.DepartCode = F.DepartCode AND D.DepartType = 3 and F.OperationType <>7	
				And F.Deleted = 0 
	Group By F.PostDate
)x On X.Postdate = Defaultdate.DefaultDate
Where DefaultDate.CompanyRecId=@CompanyRecID and DefaultDate = @ManagerDate

