From DefaultDate Left Outer Join
(
	SELECT F.postDate,  
	IsNull(Sum(LocalAmount),0) as DailyCompRoomRevenueLocal,
	IsNull(Sum(Case When F.CurrencyCode = 'EUR' Then F.NetAmount Else F.NetAmount*(Dbo.FnFoundCurr(IsNull(F.CurrDate,F.Postdate),F.CurrencyCode,1,@CompanyRecId)/Dbo.FnFoundCurr(IsNull(F.CurrDate,F.PostDate),'EUR',1,@CompanyRecId))
	End),0) As DailyCompRoomRevenueEUR,
	IsNull(Sum(Case When F.CurrencyCode = 'USD' Then F.NetAmount Else F.NetAmount*(Dbo.FnFoundCurr(IsNull(F.CurrDate,F.Postdate),F.CurrencyCode,1,@CompanyRecId)/Dbo.FnFoundCurr(IsNull(F.CurrDate,F.PostDate),'USD',1,@CompanyRecId))
	End),0) As DailyCompRoomRevenueUSD	
FROM         Reservation With (NoLock) 
INNER JOIN DailyDetail  DT With (NoLock) ON Reservation.RecId = DT.ReservationId  AND DT.CompanyRecId=@CompanyRecID
RIGHT OUTER JOIN Folio  F With (NoLock) 
LEFT OUTER JOIN Department D With (NoLock) 
ON F.DepartCode = D.DepartCode AND D.DepartType = 1  AND D.CompanyRecId=@CompanyRecID
ON DT.RecId = F.RefId AND F.CompanyRecId=@CompanyRecID
Where Reservation.CompanyRecId=@CompanyRecID and DT.StayType In (4,6) And Reservation.Status >0 And F.Deleted = 0 
	Group By F.PostDate
)x On X.Postdate = Defaultdate.DefaultDate
Where DefaultDate = @ManagerDate  AND Defaultdate.CompanyRecId=@CompanyRecID

