From DefaultDate Left Outer Join
(
--SELECT H.Room,H.HotelDate,
--	IsNull(Sum(Case When H.OOOStatus ='OOO' Then 1 Else 0 End),0) as YearlyOOORoom,
--	IsNull(Sum(Case When H.OOOStatus ='OOS' Then 1 Else 0 End),0) as YearlyOOSRoom,
--	IsNull(Sum(Case When H.OOOStatus ='OOO' Then 1 Else 0 End),0)*IsNull(Max((Rt.Capacity)),1) as YearlyOOOBed,
--	IsNull(Sum(Case When H.OOOStatus ='OOS' Then 1 Else 0 End),0)*IsNull(Max((Rt.Capacity)),1) as YearlyOOSBed
--	FROM  HkHistory H, Room R,RoomType Rt
--	Where IsNull(H.OOOStatus,'N') In ('OOO','OOS')
--	And H.RecordTime = (Select Max(h1.RecordTime) From HkHistory h1 Where H1.HotelDate =H.HotelDAte) 
--	And H.Room = R.Room And 
--	R.RoomtypeCode = Rt.RoomtypeCode
--	Group By H.Room,H.HotelDate

Select DailyDetail.StayDate,
IsNull(Sum(Case When DailyDetail.Status=3 Then 1 Else 0 End),0) as YearlyOOORoom,
IsNull(Sum(Case When DailyDetail.Status=2 Then 1 Else 0 End),0) as YearlyOOSRoom,
IsNull(Sum(Case When DailyDetail.Status=3 Then 1 Else 0 End),0)*IsNull(Max(RoomType.Capacity),1) as YearlyOOOBed,
IsNull(Sum(Case When DailyDetail.Status=2 Then 1 Else 0 End),0)*IsNull(Max(RoomType.Capacity),1) as YearlyOOSBed
From DailyDetail 
inner join Room 
inner join RoomType 
on Room.RoomTypeCode=RoomType.RoomTypeCode and  RoomType.CompanyRecId=@CompanyRecID
on DailyDetail.Room=Room.Room and  Room.CompanyRecId=@CompanyRecID
Where  DailyDetail.CompanyRecId=@CompanyRecID and Room.Forecast=1 
Group By DailyDetail.StayDate	

)x On X.StayDate = Defaultdate.DefaultDate
Where DefaultDate.CompanyRecId=@CompanyRecID and
DefaultDate<= @ManagerDate And DefaultDate >= cast('01'+'/'+'01'+'/'+Cast(Year(@ManagerDate) as VarChar(4)) as DateTime)	

