0 as BedCapacity
From DefaultDate Left Outer Join
(
    Select D.StayDate,
	IsNull(Sum(D.RoomNummer),0) as LY_DailyRoom,
	IsNull(Sum(D.RoomNummer*D.Pax),0) as LY_DailyPax,
	IsNull(Sum(D.RoomNummer*D.PaidChild),0) as LY_DailyPChd,
	IsNull(Sum(D.RoomNummer*D.FreeChild),0) as LY_DailyFChd,
	IsNull(Sum(D.RoomNummer*D.Baby),0) as LY_DailyBby,

	IsNull(Sum(Case When D.StayType < 4 Then D.RoomNummer Else 0 End),0) as LY_DailySoldRoom,
	IsNull(Sum(Case When D.StayType < 4 Then D.RoomNummer*D.Pax Else 0 End),0) as LY_DailySoldPax,
	IsNull(Sum(Case When D.StayType < 4 Then D.RoomNummer*D.PaidChild  Else 0 End),0) as LY_DailySoldPChd,
	IsNull(Sum(Case When D.StayType < 4 Then D.RoomNummer*D.FreeChild Else 0 End),0) as LY_DailySoldFChd,
	IsNull(Sum(Case When D.StayType < 4 Then D.RoomNummer*D.Baby Else 0 End),0) as LY_DailySoldBby,

	IsNull(Sum(Case When D.StayType In (4,6) Then D.RoomNummer Else 0 End) ,0) as LY_DailyCompRoom,
	IsNull(Sum(Case When D.StayType In (4,6) Then (case D.RoomNummer when 0 then 1 else D.RoomNummer end) *D.Pax Else 0 End),0) as LY_DailyCompPax,
	IsNull(Sum(Case When D.StayType In (4,6) Then D.RoomNummer*D.PaidChild Else 0 End),0) as LY_DailyCompPChd,
	IsNull(Sum(Case When D.StayType In (4,6) Then D.RoomNummer*D.FreeChild Else 0 End),0) as LY_DailyCompFChd,
	IsNull(Sum(Case When D.StayType In (4,6) Then D.RoomNummer*D.Baby Else 0 End),0) as LY_DailyCompBby,

	IsNull(Sum(Case When D.StayType =5 Then D.RoomNummer Else 0 End) ,0) as LY_DailyHouseRoom,
	IsNull(Sum(Case When D.StayType =5 Then D.RoomNummer*D.Pax Else 0 End),0) as LY_DailyHousePax,
	IsNull(Sum(Case When D.StayType =5 Then D.RoomNummer*D.PaidChild Else 0 End),0) as LY_DailyHousePChd,
	IsNull(Sum(Case When D.StayType =5 Then D.RoomNummer*D.FreeChild Else 0 End),0) as LY_DailyHouseFChd,
	IsNull(Sum(Case When D.StayType =5 Then D.RoomNummer*D.Baby Else 0 End),0) as LY_DailyHouseBby,

	IsNull(Sum(Case When D.Pax =1 Then D.RoomNummer Else 0 End) ,0) as LY_DailySngRoom,
	IsNull(Sum(Case When D.Pax =2 Then D.RoomNummer Else 0 End),0) as LY_DailyDblRoom,
	IsNull(Sum(Case When D.Pax =3 Then D.RoomNummer Else 0 End),0) as LY_DailyTrpRoom,
	IsNull(Sum(Case When D.Pax >=4 Then D.RoomNummer Else 0 End),0) as LY_DailyQuaRoom,

	IsNull(Sum(Case When D.Pax =1 Then D.Pax Else 0 End) ,0) as LY_DailySngPax,
	IsNull(Sum(Case When D.Pax =2 Then D.Pax Else 0 End),0) as LY_DailyDblPax,
	IsNull(Sum(Case When D.Pax =3 Then D.Pax Else 0 End),0) as LY_DailyTrpPax,
	IsNull(Sum(Case When D.Pax >=4 Then D.Pax Else 0 End),0) as LY_DailyQuaPax,

	IsNull(Sum(Case When D.Child1<7 And D.Child1>0 Then 1 Else 0 end)+
		   Sum(Case When D.Child2<7 And D.Child2>0 Then 1 Else 0 end)+
		   Sum(Case When D.Child3<7 And D.Child3>0 Then 1 Else 0 end)+
		   Sum(Case When D.Child4<7 And D.Child4>0 Then 1 Else 0 end),0 ) 
		 As LY_DailyChd1,

	IsNull(Sum(Case When D.Child1>=7  Then 1 Else 0 end)+
		   Sum(Case When D.Child2>=7  Then 1 Else 0 end)+
		   Sum(Case When D.Child3>=7  Then 1 Else 0 end)+
		   Sum(Case When D.Child4>=7  Then 1 Else 0 end),0 ) 
	As LY_DailyChd7



	


	From DailyDetail D With (NoLock), Reservation R With (NoLock) 
	Where D.CompanyRecId=@CompanyRecID and R.CompanyRecId=@CompanyRecID and R.RecId = D.ReservationId And R.Status>0 
	Group By D.StayDAte



)x On X.StayDate = Defaultdate.DefaultDate
Where DefaultDate.CompanyRecId=@CompanyRecID and DefaultDate = DateAdd(year, -1, @ManagerDate)
