From DefaultDate Left Outer Join
(
	SELECT F.postDate,  
	IsNull(Sum(LocalAmount),0) as LY_DailyRoomRevenueLocal,
	IsNull(Sum(LocalAmount/(1+(F.VatRatio*0.01))),0) as LY_DailyVORoomRevenueLocal,
	IsNull(Sum(Case When F.CurrencyCode = 'EUR' Then F.NetAmount Else F.NetAmount*(Dbo.FnFoundCurr(IsNull(F.CurrDate,F.Postdate),F.CurrencyCode,1,@CompanyRecId)/Dbo.FnFoundCurr(IsNull(F.CurrDate,F.PostDate),'EUR',1,@CompanyRecId))
	End),0) As LY_DailyRoomRevenueEUR,

	IsNull(Sum(Case When F.CurrencyCode = 'EUR' Then F.NetAmount/(1+(F.VatRatio*0.01)) Else (F.NetAmount/(1+(F.VatRatio*0.01)))*(Dbo.FnFoundCurr(IsNull(F.CurrDate,F.Postdate),F.CurrencyCode,1,@CompanyRecId)/Dbo.FnFoundCurr(IsNull(F.CurrDate,F.PostDate),'EUR',1,@CompanyRecId))
	End),0) As LY_DailyVORoomRevenueEUR,

	IsNull(Sum(Case When F.CurrencyCode = 'USD' Then F.NetAmount Else F.NetAmount*(Dbo.FnFoundCurr(IsNull(F.CurrDate,F.Postdate),F.CurrencyCode,1,@CompanyRecId)/Dbo.FnFoundCurr(IsNull(F.CurrDate,F.PostDate),'USD',1,@CompanyRecId))
	End),0) As LY_DailyRoomRevenueUSD,	

	IsNull(Sum(Case When F.CurrencyCode = 'USD' Then F.NetAmount/(1+(F.VatRatio*0.01)) Else (F.NetAmount/(1+(F.VatRatio*0.01)))*(Dbo.FnFoundCurr(IsNull(F.CurrDate,F.Postdate),F.CurrencyCode,1,@CompanyRecId)/Dbo.FnFoundCurr(IsNull(F.CurrDate,F.PostDate),'USD',1,@CompanyRecId))
	End),0) As LY_DailyVORoomRevenueUSD	


	FROM         Department D With (NoLock), Folio F  With (NoLock) 
	Where D.CompanyRecId=@CompanyRecID and F.CompanyRecId=@CompanyRecID and  D.DepartCode = F.DepartCode AND D.DepartType = 1
				And F.Deleted = 0 
	Group By F.PostDate
)x On X.Postdate = Defaultdate.DefaultDate
Where DefaultDate.CompanyRecId=@CompanyRecID and DefaultDate = DateAdd(year, -1, @ManagerDate)

