From DefaultDate Left Outer Join
(
	SELECT F.postDate,  
	

	IsNull(Sum(Case When DailyDetail.Pax = 1 Then LocalAmount Else 0 End),0) as LY_DailySngRoomRevenue,
	IsNull(Sum(Case When DailyDetail.Pax = 2 Then LocalAmount Else 0 End),0) as LY_DailyDblRoomRevenue,
	IsNull(Sum(Case When DailyDetail.Pax = 3 Then LocalAmount Else 0 End),0) as LY_DailyTrpRoomRevenue,
	IsNull(Sum(Case When DailyDetail.Pax >= 4 Then LocalAmount Else 0 End),0) as LY_DailyQuaRoomRevenue

	
	FROM         Department D With (NoLock), Folio F With (NoLock), DailyDetail With (NoLock) , Reservation With (NoLock) 
	Where D.CompanyRecId=@CompanyRecID and F.CompanyRecId=@CompanyRecID and DailyDetail.CompanyRecId=@CompanyRecID and  
	 Reservation.CompanyRecId=@CompanyRecID and 
	Reservation.recId = DailyDetail.reservationId And 
	D.DepartCode = F.DepartCode AND D.DepartType = 1 and DailyDetail.RecId = F.RefId And F.Deleted = 0 And Reservation.Status >0 
	Group By F.PostDate
)x On X.Postdate = Defaultdate.DefaultDate
Where Defaultdate.CompanyRecId=@CompanyRecID and  DefaultDate = DateAdd(year, -1, @ManagerDate)


Union All
