From DefaultDate Left Outer Join
(

	Select 
 (Select Defaultdate From Defaultdate Where Defaultdate.CompanyRecId=@CompanyRecID and  Defaultdate =@ManagerDate) as PostDate,
	Case When @AvailableRoom=0 Then
	Count(RecId) 
	 Else Count(RecId)-IsNull((Select Count(RecId) From dailyDetail Where DailyDetail.CompanyRecId=@CompanyRecID and  StayDate = @ManagerDate And Status = 4),0)
	End as RoomCapacity  
	From room  Where Room.CompanyRecId=@CompanyRecID and  Forecast=1 
)x On X.Postdate = Defaultdate.DefaultDate
Where Defaultdate.CompanyRecId=@CompanyRecID and  DefaultDate = @ManagerDate

