	Case When  @AvailableRoom = 0 Then 
		Sum(RoomType.Capacity) 
		Else
		Sum(RoomType.Capacity)-IsNull((Select Sum(RoomType.Capacity) FRom DailyDetail,Room, RoomType 
		Where DailyDetail.CompanyRecId=@CompanyRecID and  Room.CompanyRecId=@CompanyRecID and  RoomType.CompanyRecId=@CompanyRecID and 
			dailydetail.Room = Room.Room And Room.RoomTypeCode = RoomType.RoomTYpeCode And Room.Forecast=1 And
			DailyDetail.Status = 4 And DailyDetail.Staydate = @ManagerDate),0)
		End as BedCapacity

	
	From Room,RoomType Where Room.CompanyRecId=@CompanyRecID and RoomType.CompanyRecId=@CompanyRecID and   Room.Forecast = 1 And Room.RoomTypecode = RoomTYpe.RoomTypeCode

